async def handle_stock_proposals(request):
    """Builds proposals from the pre-assignment F5 visual plan and script timing."""
    try:
        data = await request.json()
        story_dir = Path(data.get("story_dir", ""))
        if not story_dir.is_dir():
            return web.json_response({"status": "error", "message": "Story directory not found."}, status=404)
        srt_files = list(story_dir.glob("*.srt"))
        if not srt_files:
            return web.json_response({"status": "error", "message": "An SRT script is required to plan F5 shot timing."}, status=404)
        cues = parse_srt_file(srt_files[0])
        total_duration = cues[-1].end_sec if cues else 0.0
        storyboard_file = story_dir / "gemini_storyboard.json"
        storyboard = json.loads(storyboard_file.read_text(encoding="utf-8")) if storyboard_file.is_file() else {}
        planned_visuals = storyboard.get("body_scenes", []) if isinstance(storyboard, dict) else []
        if not isinstance(planned_visuals, list):
            planned_visuals = []

        # F5 plans one stock shot per 30 second interval. Use the matching planned
        # storyboard visual when available; narration supplies context only.
        shots = []
        from ..stages.stage2_assets.stock_proposals import compile_stock_proposal_table
        narration_by_range = {}
        def stamp(seconds):
            total = max(0, int(seconds))
            return f"{total // 60}:{total % 60:02d}"
        for index, start_sec in enumerate(range(0, int(total_duration), 30)):
            end_sec = min(start_sec + 30, total_duration)
            time_range = f"{stamp(start_sec)} - {stamp(end_sec)}"
            narration_by_range[time_range] = " ".join(
                cue.text for cue in cues if cue.start_sec < end_sec and cue.end_sec > start_sec
            )
            planned = planned_visuals[index] if index < len(planned_visuals) and isinstance(planned_visuals[index], dict) else {}
            visual = planned.get("visual_description") or planned.get("visual_intent") or planned.get("description") or planned.get("prompt") or ""
            shots.append({
                "shot_index": index + 1, "time_range": time_range,
                "dramatic_beat": planned.get("dramatic_beat", planned.get("title", "")),
                "visual_description": visual,
                "shot_type": planned.get("shot_type", ""),
                "location": planned.get("location", ""),
                "characters_present": planned.get("characters_present", []),
            })
        client = PexelsClient()
        loop = asyncio.get_event_loop()
        table = await loop.run_in_executor(None, lambda: compile_stock_proposal_table(shots, client, narration_by_range))
        return web.json_response(table)
    except Exception as e:
        return web.json_response({"status": "error", "message": str(e)}, status=500)

